INSERT INTO `tblitems` (`id`, `description`, `long_description`, `rate`, `tax`, `tax2`, `unit`, `group_id`, `rate_currency_3`) VALUES
(8, 'CRM Software License', 'Comprehensive CRM solution for managing leads, sales pipeline, customer communication, follow-ups, reporting, and automation. Includes dashboard analytics, user management, and API integration support.', 25000.00, 3, NULL, 'License', 10, NULL),
(9, 'ERP Software License', 'Complete ERP solution covering finance, procurement, sales, HR, operations, reporting, and inventory management. Suitable for SMEs and enterprises with customizable modules and multi-user access.', 75000.00, 3, NULL, 'License', 10, NULL),
(10, 'Billing Software', 'Billing software with GST-compliant invoicing, purchase management, expense tracking, barcode billing, customer ledger, and financial reports. Supports multi-user and multi-branch.', 12000.00, 3, NULL, 'License', 10, NULL),
(11, 'Inventory Management Software', 'Advanced inventory tracking system with stock monitoring, warehouse management, batch/expiry tracking, reorder alerts, barcode support, and integration with billing/ERP systems.', 18000.00, 3, NULL, 'License', 10, NULL),
(12, 'HRMS Software', 'Complete HRMS solution including employee management, payroll processing, attendance tracking, leave management, statutory compliance, and performance evaluation.', 30000.00, 3, NULL, 'License', 10, NULL),
(13, 'CRM Monthly Subscription', 'Cloud-based CRM subscription for managing leads, sales pipeline, follow-ups, customer database, reporting dashboard, and automation tools. Includes technical support and updates.', 2499.00, 3, NULL, 'User / Month', 11, NULL),
(14, 'ERP Monthly Subscription', 'Complete ERP system subscription including finance, purchase, sales, inventory, HR, reporting, and multi-user access. Cloud-hosted with secure login and automatic updates.', 5999.00, 3, NULL, 'User / Month', 11, NULL),
(15, 'SaaS Annual Plan', 'Full access to selected SaaS modules (CRM/ERP/Billing/Inventory/HRMS) for 12 months. Includes hosting, maintenance, upgrades, and priority support.', 29999.00, NULL, NULL, 'License / Year', 11, NULL),
(16, 'API Subscription Plan', 'Secure API access subscription for integration with third-party systems. Includes API documentation, authentication keys, rate limits, and technical support.', 15000.00, 3, NULL, 'Subscription / Month', 11, NULL),
(17, 'Cloud Software Subscription', 'Fully hosted cloud software subscription with data backup, SSL security, server maintenance, uptime monitoring, and remote access from anywhere.', 3999.00, NULL, NULL, 'User / Month', 11, NULL),
(18, 'Static Website Development', 'Development of responsive static websites with modern UI/UX design. Includes homepage, about page, services, contact form, and mobile optimization. Suitable for small businesses and startups.', 25000.00, 3, NULL, 'Project', 13, NULL),
(19, ' E-commerce Website', 'Complete online store development with product catalog, cart system, payment gateway integration, order management, inventory integration, and admin dashboard.', 120000.00, 3, NULL, 'Project', 13, NULL),
(20, 'WordPress Website', 'Professional WordPress website with premium theme setup, plugin configuration, SEO-friendly structure, contact forms, and performance optimization.', 35000.00, NULL, NULL, 'Project', 13, NULL),
(21, 'Website Redesign', 'Redesign of existing website with improved UI/UX, performance optimization, modern layout, responsive design, and updated content structure.', 30000.00, NULL, NULL, 'Project', 13, NULL),
(22, 'Mobile App Development Service', 'Complete Android & iOS mobile application development service including UI/UX design, API integration, payment gateway setup, admin panel development, testing, deployment on Play Store & App Store, and post-launch technical support. Suitable for startups, fintech companies, ecommerce platforms, and service-based businesses.', 50000.00, NULL, NULL, 'Project', 14, NULL),
(23, 'REST API Development', 'Secure and scalable RESTful API development using modern backend technologies. Includes database integration, authentication (JWT/OAuth), CRUD operations, API documentation, testing, and cloud deployment. Suitable for mobile apps, web applications, ERP systems, and SaaS platforms.', 150000.00, NULL, NULL, 'Project', 15, NULL),
(24, 'Payment API Development', 'Development and integration of secure payment APIs including UPI, wallet systems, payout APIs, settlement systems, transaction logs, webhook handling, encryption, and compliance support. Ideal for fintech platforms, DMT services, ecommerce, and financial institutions', 150000.00, 3, NULL, 'Project', 15, NULL),
(25, 'Custom API Development', 'Fully customized API solutions tailored to business requirements including workflow automation, multi-user roles, admin dashboards, reporting modules, and secure data exchange. Designed for startups, enterprises, and SaaS businesses.', 200000.00, 3, NULL, 'Project', 15, NULL),
(26, 'Third-party API Creation / Integration', 'Integration and configuration of third-party APIs such as SMS gateways, payment gateways, KYC providers, travel booking APIs, shipping APIs, CRM systems, and analytics tools. Includes testing, documentation, and monitoring setup.', 75000.00, 3, NULL, 'Project', 15, NULL),
(27, 'Payment Gateway Integration', 'Integration of secure online payment gateway including UPI, Credit/Debit Cards, Net Banking, Wallets with API documentation, testing, and deployment support.', 15000.00, 3, NULL, 'Project', 16, NULL),
(28, 'SMS API Integration', 'Transactional & OTP SMS API integration with DLT registration support, sender ID setup, template approval, and delivery report configuration.', 5000.00, NULL, NULL, 'Project', 16, NULL),
(29, 'WhatsApp API Integration', 'Official WhatsApp Business API integration including template approval, webhook setup, chatbot connection, and automation support.', 25000.00, 3, NULL, 'Project', 16, NULL),
(30, 'Travel API Integration', 'Flight, Hotel, Bus & Train API integration with search, booking, cancellation, mark-up management, and admin panel configuration.', 30000.00, NULL, NULL, 'Project', 16, NULL),
(31, 'Fintech API Integration', 'Integration of AEPS, DMT, BBPS, Micro ATM, PAN, KYC APIs with secure authentication, wallet system connectivity, and compliance support', 75000.00, NULL, NULL, 'Project', 16, NULL),
(32, 'AEPS API Integration', 'Integration of Aadhaar Enabled Payment System API including balance inquiry, cash withdrawal, mini statement, authentication & testing support.\r\n', 35000.00, 3, NULL, 'Project', 17, NULL),
(33, 'DMT API Integration', 'Integration of DMT API with bank validation, beneficiary management, transaction processing & admin panel configuration.', 40000.00, 3, NULL, 'Project', 17, NULL),
(34, 'BBPS API Integration', 'Bharat Bill Payment API Integration\r\nLong Description: Complete BBPS bill payment system integration with operator setup, transaction reporting & reconciliation system.', 45000.00, NULL, NULL, 'Project', 17, NULL),
(35, 'Recharge API Integration', 'Mobile & DTH Recharge API\r\nLong Description: Multi-operator recharge API integration including prepaid, postpaid, DTH & data card services.\r\n', 25000.00, NULL, NULL, 'Project', 17, NULL),
(36, 'KYC Verification API', 'Aadhaar, PAN, GST, Bank Account & Document verification API integration with secure authentication.', 30000.00, 3, NULL, 'Project', 17, NULL),
(37, 'Payment Gateway Setup', 'Payment Gateway Setup', 25000.00, NULL, NULL, 'Project', 18, NULL),
(38, 'CBS Software License', 'Complete Core Banking Software including customer management, account management, transaction processing, loan module, reporting, and admin panel access.', 450000.00, 3, NULL, 'Project', 10, NULL),
(39, 'Cloud Server Setup', 'Deployment of cloud server including OS installation, security configuration, firewall setup, database configuration, and performance optimization.', 25000.00, 3, NULL, 'Project', 19, NULL),
(40, ' Shared Web Hosting Plan', '1-year web hosting including cPanel access, email setup, daily backup, SSL support, and basic security protection.', 12000.00, 3, NULL, 'Project', 19, NULL),
(41, 'VPS Hosting', 'Dedicated virtual server with allocated CPU, RAM, SSD storage, root access, firewall protection, and uptime monitoring.', 30000.00, 3, NULL, 'Project', 19, NULL),
(42, 'Dedicated Server Setup', 'Complete physical dedicated server setup with high performance configuration, advanced security setup, backup configuration, and monitoring tools.', 75000.00, 3, 3, 'Project', 19, NULL),
(43, 'SSL Installation', 'Installation and configuration of SSL certificate to enable HTTPS security, data encryption, and secure browser authentication.', 3000.00, 3, NULL, 'Project', 19, NULL),
(44, 'Software Server chrge', '', 11900.00, NULL, NULL, '', 0, NULL);
