(466, 'sms_trigger_invoice_overdue_notice', 'Subject (Email): Invoice Overdue – Immediate Attention Required<br />\r\n<br />\r\nMessage:<br />\r\n<br />\r\nDear {contact_firstname},<br />\r\n<br />\r\nThis is a reminder that Invoice #{invoice_number} issued by Dealplex was due on {invoice_duedate} and is currently overdue.<br />\r\n<br />\r\nOutstanding Amount: {invoice_balance_due}<br />\r\n<br />\r\nKindly arrange payment at the earliest to avoid service interruption or late charges.<br />\r\n<br />\r\nFor assistance, please contact our billing team.<br />\r\n<br />\r\nRegards,<br />\r\nDealplex Accounts Team', 0),
(467, 'sms_trigger_invoice_due_notice', 'Subject (Email): Invoice Overdue – Immediate Attention Required<br />\r\n<br />\r\nMessage:<br />\r\n<br />\r\nDear {contact_firstname},<br />\r\n<br />\r\nThis is a reminder that Invoice #{invoice_number} issued by Dealplex was due on {invoice_duedate} and is currently overdue.<br />\r\n<br />\r\nOutstanding Amount: {invoice_balance_due}<br />\r\n<br />\r\nKindly arrange payment at the earliest to avoid service interruption or late charges.<br />\r\n<br />\r\nFor assistance, please contact our billing team.<br />\r\n<br />\r\nRegards,<br />\r\nDealplex Accounts Team', 0),
(468, 'sms_trigger_invoice_payment_recorded', 'Invoice Payment Recorded<br />\r\n<br />\r\nSubject: Payment Received – Thank You<br />\r\n<br />\r\nMessage:<br />\r\n<br />\r\nDear {contact_firstname},<br />\r\n<br />\r\nWe have successfully received payment for Invoice #{invoice_number}.<br />\r\n<br />\r\nPaid Amount: {invoice_amount_paid}<br />\r\nPayment Date: {payment_date}<br />\r\n<br />\r\nThank you for your prompt payment and continued trust in Dealplex.<br />\r\n<br />\r\nRegards,<br />\r\nDealplex Accounts Team', 0),
(469, 'sms_trigger_estimate_expiration_reminder', 'Subject: Estimate Expiring Soon – Action Required<br />\r\n<br />\r\nMessage:<br />\r\n<br />\r\nHello {contact_firstname},<br />\r\n<br />\r\nThis is a reminder that Estimate #{estimate_number} issued by Dealplex is set to expire on {estimate_expirydate}.<br />\r\n<br />\r\nPlease review and confirm your acceptance before expiry to lock pricing and availability.<br />\r\n<br />\r\nRegards,<br />\r\nDealplex Sales Team', 0),
(470, 'sms_trigger_proposal_expiration_reminder', 'Subject: Proposal Expiring Soon<br />\r\n<br />\r\nMessage:<br />\r\n<br />\r\nDear {contact_firstname},<br />\r\n<br />\r\nThe proposal #{proposal_number} shared with you will expire on {proposal_expirydate}.<br />\r\n<br />\r\nKindly review and respond before the expiration date to proceed further.<br />\r\n<br />\r\nRegards,<br />\r\nDealplex', 0),
(471, 'sms_trigger_proposal_new_comment_to_customer', 'New Comment on Proposal (To Customer)<br />\r\n<br />\r\nMessage:<br />\r\n<br />\r\nHello {contact_firstname},<br />\r\n<br />\r\nA new comment has been added to Proposal #{proposal_number} by the Dealplex team.<br />\r\n<br />\r\nPlease log in to view the update and respond if required.<br />\r\n<br />\r\n– Dealplex', 0),
(472, 'sms_trigger_proposal_new_comment_to_staff', 'New Comment on Proposal (To Staff)<br />\r\n<br />\r\nMessage:<br />\r\n<br />\r\nNotification:<br />\r\n<br />\r\nA new comment has been added by the customer on Proposal #{proposal_number}.<br />\r\n<br />\r\nPlease review and take necessary action.<br />\r\n<br />\r\n– Dealplex System', 0),
(473, 'sms_trigger_contract_new_comment_to_customer', 'System<br />\r\n<br />\r\n💬 New Comment on Contract (To Customer)<br />\r\n<br />\r\nMessage:<br />\r\n<br />\r\nDear {contact_firstname},<br />\r\n<br />\r\nA new comment has been added by Dealplex on Contract #{contract_number}.<br />\r\n<br />\r\nPlease log in to review the update.<br />\r\n<br />\r\nRegards,<br />\r\nDealplex', 0),
(474, 'sms_trigger_contract_new_comment_to_staff', 'New Comment on Contract (To Staff)<br />\r\n<br />\r\nMessage:<br />\r\n<br />\r\nAlert:<br />\r\n<br />\r\nA new comment has been added by the customer on Contract #{contract_number}.<br />\r\n<br />\r\nPlease review and respond as needed.<br />\r\n<br />\r\n– Dealplex System', 0),
(475, 'sms_trigger_contract_expiration_reminder', 'Subject: Contract Expiry Reminder<br />\r\n<br />\r\nMessage:<br />\r\n<br />\r\nDear {contact_firstname},<br />\r\n<br />\r\nThis is a reminder that Contract #{contract_number} with Dealplex is set to expire on {contract_expirydate}.<br />\r\n<br />\r\nPlease contact us to renew or discuss continuation of services.<br />\r\n<br />\r\nRegards,<br />\r\nDealplex Contracts Team', 0),
(476, 'sms_trigger_contract_sign_reminder_to_customer', 'Contract Sign Reminder<br />\r\n<br />\r\nSubject: Contract Signature Pending<br />\r\n<br />\r\nMessage:<br />\r\n<br />\r\nHello {contact_firstname},<br />\r\n<br />\r\nThe contract #{contract_number} sent by Dealplex is pending your signature.<br />\r\n<br />\r\nKindly sign at the earliest to proceed with services.<br />\r\n<br />\r\nRegards,<br />\r\nDealplex', 0),
(477, 'sms_trigger_staff_reminder', 'Staff Reminder<br />\r\n<br />\r\nMessage:<br />\r\n<br />\r\nReminder:<br />\r\n<br />\r\nYou have a scheduled task/reminder regarding {reminder_description}.<br />\r\n<br />\r\nDue Date: {reminder_date}<br />\r\n<br />\r\nPlease take necessary action.<br />\r\n<br />\r\n– Dealplex System', 0),
