INSERT INTO `tbltemplates` (`id`, `name`, `type`, `addedfrom`, `content`, `content_type`) VALUES
(1, 'Dealplex Contract Creation & Acceptance Notice', 'contracts', 1, '<p class=\"MsoNormal\"><span></span></p><p></p>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>&#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; DEALPLEX DARKSTORE &#8211; LITE</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>&#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; FRANCHISE AGREEMENT (Neighbourhood Node)</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<p></p>\n<p class=\"MsoNormal\"><b><span>1&#65039; </span></b><b><span>PARTIES</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;This Agreement is entered into between:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Dealplex,a company having its registered office at Office No. 528A, 5th Floor, Gera\'s Imperium Rise, Rajiv Gandhi Infotech Park (Hinjawadi), Pune, Haveli, Maharashtra, India &#8211; 411057,</span></b><b><span><br></span></b><b><span>(hereinafter referred to as the &#8220;Company&#8221;, which expression shall, unless repugnant to the context or meaning thereof, include its successors and permitted assigns),</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>AND</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>[Franchisee Name],</span></b><b><span><br></span></b><b><span>having its registered / principal place of business at [Franchisee Address],</span></b><b><span><br></span></b><b><span>(hereinafter referred to as the &#8220;DarkStore Partner&#8221; or &#8220;Franchisee&#8221;, which expression shall, unless repugnant to the context or meaning thereof, include its successors and permitted assigns).</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>OBJECT OF AGREEMENT</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span>The Company hereby appoints the Franchisee, on a </span><b><span>non-exclusive, limited and revocable basis</span></b><span>, to establish, operate and manage a </span><b><span>Dealplex DarkStore &#8211; LITE</span></b><span>, functioning as a </span><b><span>Neighbourhood Node</span></b><span>, solely for the purpose of fulfilling </span><b><span>hyperlocal quick commerce orders</span></b><span>&#160;generated through the Company&#8217;s technology platform, within such </span><b><span>micro-catchment area as may be allocated, modified or re-defined by the Company from time to time</span></b><span>.</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><span>The Franchisee expressly acknowledges that the Company shall have </span><b><span>absolute discretion and control</span></b><span>&#160;over the business model, technology platform, product catalogue, pricing, promotional schemes, order allocation and service standards, and that the Franchisee shall operate the Dealplex DarkStore &#8211; LITE strictly in accordance with the </span><b><span>policies, standard operating procedures (SOPs), service level requirements and directions</span></b><span>&#160;issued by the Company from time to time.</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><span>The Franchisee shall not use the Dealplex DarkStore &#8211; LITE for any purpose other than the fulfillment of orders routed through the Company&#8217;s platform, nor shall the Franchisee provide similar or competing services, directly or indirectly, without the </span><b><span>prior written consent of the Company</span></b><span>.</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><b><span>3&#65039; </span></b><b><span>STORE FORMAT &amp; PURPOSE</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>3.1 Store Format</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The DarkStore operated under this Agreement shall be designated as &#8220;Dealplex DarkStore &#8211; LITE&#8221;, which shall function as a Neighbourhood Node within the Company&#8217;s hyperlocal quick commerce network. The DarkStore &#8211; LITE shall be a closed-user fulfilment facility and shall not operate as a walk-in retail store or allow direct customer access, except as expressly permitted in writing by the Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>3.2 Purpose of the Store</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The primary purpose of the Dealplex DarkStore &#8211; LITE shall be to enable:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>a) Ultra-fast order fulfillment, with a targeted delivery time of 10 to 30 minutes, subject to demand patterns, traffic conditions, system allocation and operational feasibility;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>b) Low-cost, high-frequency order processing, optimized for daily essentials, fast-moving consumer goods and other categories as determined by the Company from time to time; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>c) Efficient execution of the Company&#8217;s hyperlocal quick commerce strategy, with strict adherence to the operational, service level and quality benchmarks prescribed by the Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>3.3 Target Catchment Area</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Dealplex DarkStore &#8211; LITE shall primarily service dense residential pockets, apartment clusters and high-frequency demand zones, within such delivery radius and micro-catchment area as may be defined, modified, expanded or restricted by the Company at its sole discretion from time to time, based on demand density, network optimisation and service efficiency.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>3.4 Demand Capacity &amp; Performance Expectation</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Dealplex DarkStore &#8211; LITE is designed to support a peak operational capacity of approximately 250 to 1,200 customer orders per day, subject to market conditions, seasonality and operational capability.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee acknowledges that:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The stated demand capacity is indicative and non-guaranteed;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Actual order volumes shall depend on factors including customer demand, marketing initiatives, system allocation and overall network performance; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company shall have the right to re-route, limit or reallocate orders to other fulfilment centres in the interest of service quality and network efficiency.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>3.5 Company Control &amp; Modification Rights</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall have the unrestricted right to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Modify the store format, layout, operating model or service scope;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Change delivery timelines, demand allocation logic or capacity thresholds;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Introduce or withdraw product categories, SKUs or service offerings; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Integrate the Dealplex DarkStore &#8211; LITE into a broader city-level or regional fulfilment strategy.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall implement all such changes without objection and within timelines prescribed by the Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>3.6 No Assurance of Business</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee expressly agrees and acknowledges that:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company does not guarantee any minimum order volume, revenue or profitability; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>All business risks related to demand fluctuation, operational costs and execution shall be borne solely by the Franchisee.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>4&#65039;</span></b><b><span><span style=\"font-family:\'Segoe UI Symbol\';\">&#8419;</span></span></b><b><span>&#160;TERRITORY &amp; CATCHMENT</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>4.1 Defined Delivery Radius</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Dealplex DarkStore &#8211; LITE shall operate within a delivery radius of up to 0 to 3 kilometres, measured from the store location, or such other radius as may be determined, modified, expanded or reduced by the Company from time to time, based on demand density, operational feasibility and network optimisation.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall not deliver orders beyond the permitted delivery radius without the prior written approval of the Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>4.2 Non-Exclusive Territory</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The territory allocated to the Franchisee under this Agreement shall be strictly non-exclusive. The Franchisee expressly acknowledges that:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>No exclusivity, territorial protection or right of first refusal is granted; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company shall be free to appoint additional franchisees, partners, warehouses or fulfilment centres within the same or overlapping territory without any obligation to compensate the Franchisee.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>4.3 Company Rights to Expand Network</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall have the absolute and unrestricted right, at its sole discretion, to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Open, operate or license additional Dealplex DarkStores, warehouses, hubs or fulfilment centres;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Appoint third-party service providers or company-owned stores; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Restructure the fulfilment network within the city or region for operational efficiency.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Such actions shall not constitute a breach of this Agreement nor entitle the Franchisee to any claim, compensation or adjustment.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>4.4 Order Routing &amp; System Logic</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>All customer orders shall be system-assigned through the Company&#8217;s technology platform based on proprietary algorithms, including but not limited to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Distance and rider availability</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Inventory availability</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Store performance and SLA compliance</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Network optimisation parameters</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall have the right to re-route, divert, limit, prioritise or withhold orders from the Franchisee&#8217;s DarkStore at any time, without prior notice, in the interest of service quality, customer experience or operational efficiency.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>4.5 No Right to Demand Orders</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall have no right or entitlement to demand:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>A minimum number of orders</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Guaranteed delivery volume</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Fixed service area or catchment</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee expressly waives any claim arising out of reduction, diversion or reallocation of orders by the Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>4.6 Compliance with Territory Restrictions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall strictly comply with all territorial and catchment limitations as communicated by the Company. Any unauthorised delivery outside the permitted area shall be deemed a material breach of this Agreement and may attract penalties, suspension or termination.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>5&#65039;</span></b><b><span><span style=\"font-family:\'Segoe UI Symbol\';\">&#8419;</span></span></b><b><span>&#160;FRANCHISEE RESPONSIBILITIES</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall be solely, exclusively and entirely responsible for establishing, operating and maintaining the physical infrastructure of the Dealplex DarkStore &#8211; LITE, at its own cost, risk and expense, in accordance with the specifications, standards and directions issued by the Company from time to time.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>5.1 Store Premises</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>a) Identify, lease and retain lawful possession of a suitable premises at its own cost, including payment of rent, security deposit, brokerage and all related charges;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>b) Ensure that the premises is used exclusively for operating the Dealplex DarkStore &#8211; LITE and for no other commercial or non-commercial purpose;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>c) Maintain the premises in a clean, hygienic, safe and operational condition at all times; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>d) Bear full responsibility for any disputes, eviction notices, landlord claims or third-party issues relating to the premises.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall have no responsibility or liability whatsoever in relation to the premises.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>5.2 Utilities &amp; Facilities</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall independently arrange, install, operate and maintain, at its own cost:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Continuous electricity supply with adequate backup</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>High-speed and reliable internet connectivity</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Water supply and sanitation facilities</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>CCTV surveillance systems as per Company specifications</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Fire safety equipment and compliance with applicable safety norms</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Any interruption, failure or deficiency in utilities shall be deemed the sole responsibility of the Franchisee and shall not excuse any breach of service levels or operational obligations.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>5.3 Storage &amp; Equipment</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall procure, install and maintain, at its own expense:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Racks, shelving and storage systems as per Company-approved layout</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Cold storage units, chillers and freezers for temperature-sensitive products</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Backup power for refrigeration equipment</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Any additional equipment required to meet operational or category-specific requirements</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>All equipment shall meet the technical, safety and operational standards prescribed by the Company and shall be subject to inspection and audit.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>5.4 Compliance &amp; Maintenance</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Ensure compliance with all applicable building, fire, safety and municipal regulations;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Carry out regular maintenance, servicing and repairs of the premises and equipment; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Immediately rectify any deficiencies pointed out by the Company or its authorised representatives.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Failure to maintain infrastructure standards may result in penalties, suspension of order routing or termination of this Agreement.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>5.5 No Company Liability</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee expressly acknowledges and agrees that:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company shall not bear any cost relating to rent, utilities, equipment or maintenance;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company shall not be liable for any loss, damage, accident or disruption arising out of the store premises or infrastructure; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>All risks associated with the store and infrastructure shall be borne solely by the Franchisee.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>INVENTORY &amp; OPERATIONS </span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company (Dealplex) shall have exclusive, absolute, and unrestricted rights over the supply of inventory.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>All inventory, stock, products, SKUs, consumables, and saleable items shall be supplied only by </span></b><b><i><span>The Company (Dealplex)</span></i></b><b><span>&#160;or vendors expressly approved by The Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Franchisee shall have zero rights to procure, source, substitute, or stock any product from:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Local markets</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Third-party distributors</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Parallel / grey markets</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Online or offline wholesalers</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company (Dealplex) shall retain absolute control over:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Product assortment</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Brand selection</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Pricing (MRP, selling price, discounts)</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Pack sizes, variants, and discontinuation</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Any violation shall constitute gross misconduct and material breach, entitling The Company to immediate suspension or termination without notice.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>&#160;2. DEALPLEX-APPROVED VENDOR POLICY</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company (Dealplex) may appoint, replace, or remove approved vendors at its sole discretion.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Franchisee shall not negotiate pricing, credit terms, or delivery conditions with any vendor.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>All purchases must be:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Routed strictly through Dealplex ERP / systems</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Billed as per instructions issued by The Company</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>3. INVENTORY OWNERSHIP &amp; CONTROL</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Unless otherwise stated in writing by The Company (Dealplex):</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Inventory shall be deemed Dealplex-authorized stock.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company reserves the right to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Recall inventory</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Replace slow-moving items</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Introduce or discontinue any SKU</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall act only as a custodian of inventory, and not as an independent trader or owner.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span><span style=\"font-family:Calibri;\">&#65533;&#65533;</span> 4. INVENTORY HANDLING &amp; FIFO COMPLIANCE</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall strictly follow Dealplex SOPs, including:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>FIFO (First In First Out)</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Storage &amp; shelving norms</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Temperature, hygiene, and food-safety standards</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>All handling must be exactly as prescribed by The Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>&#160;5. EXPIRY, DAMAGE &amp; UNSALEABLE STOCK</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Expired, damaged, leaked, or tampered stock must be:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Immediately segregated</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Logged in Dealplex systems</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Disposal / return shall be only as instructed by The Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Unauthorized sale or disposal shall attract:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Financial penalties</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Legal action</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Franchise termination</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>6. STOCK LOSS, PILFERAGE &amp; SHRINKAGE</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall be fully and solely liable for:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Theft</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Pilferage</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Mishandling damage</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>System mismatch</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Any shortage shall be entirely borne by the Franchisee, regardless of inventory ownership.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>&#160;MANPOWER (FRANCHISEE RESPONSIBILITY)</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Hiring &amp; management of:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Store Manager</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Pickers / Packers</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Salaries, attendance, discipline, PF/ESI (if applicable) shall be solely Franchisee&#8217;s responsibility.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company (Dealplex) shall have no employer&#8211;employee relationship with store staff.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span><span style=\"font-family:Calibri;\">&#65533;&#65533;</span> LEGAL &amp; REGULATORY COMPLIANCE</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall obtain and maintain:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>GST</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>FSSAI</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Shop &amp; Establishment</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Labour law compliances</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>All penalties, fines, or legal actions due to non-compliance shall be borne solely by the Franchisee, with no liability on The Company (Dealplex).</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span><span style=\"font-family:\'Segoe UI Emoji\';\">&#9878;&#65039; ABSOLUTE RIGHTS OF THE COMPANY (DEALPLEX)</span></span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company (Dealplex) reserves the unrestricted right to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Conduct surprise audits</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Modify inventory mix or pricing</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Impose penalties &amp; deductions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Suspend or terminate franchise operations</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Withhold payouts in case of violations</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>KEY LEGAL STATEMENT </span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span><span style=\"font-family:\'Segoe UI Emoji\';\">&#8220;The Franchisee expressly acknowledges that all inventory supplied under this Agreement is controlled exclusively by The Company, and the Franchisee shall have no independent rights to procure, source, substitute, or deal in any products whatsoever.&#8221;</span></span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>6. Responsibilities of the Company</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company&#8217;s responsibilities under this Agreement shall be limited to providing centralized platform support, brand enablement, and system-level governance. The Company shall not be responsible for day-to-day store operations or local execution.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>6.1 Technology &amp; Platform Infrastructure</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall be responsible for:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Development, maintenance, and operation of the customer mobile application.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Backend systems for order management, routing, and inventory synchronization.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>POS integration as prescribed by the Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Centralized payment gateway integration and refund processing.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall make reasonable efforts to ensure system uptime; however, it shall not be liable for disruptions caused by third-party service providers, internet outages, or hardware failures at the store level.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>6.2 Marketing, Branding &amp; Demand Generation</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company may, at its discretion:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Undertake customer acquisition initiatives and app install campaigns.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Execute digital marketing, branding, and promotional activities.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Design and run coupons, cashback, referral programs, and seasonal offers.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company does not guarantee minimum order volume, revenue, or profitability to the Franchisee.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>6.3 Pricing, Catalogue &amp; Commercial Strategy</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall retain centralized control over:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Product catalogue structure and SKU listings.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Pricing, discounting, and promotional offer strategies.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Vendor onboarding, commercial negotiations, and margin structures.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>All pricing and catalogue decisions made by the Company shall be binding on the Franchisee.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>6.4 Vendor &amp; Supply Chain Enablement</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Identify and approve vendors for inventory supply.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Define procurement processes and system workflows.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Monitor supply performance and make changes as required.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall not be responsible for losses arising due to improper storage, mishandling, or negligence at the Franchisee&#8217;s store.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>6.5 Training, SOPs &amp; Operational Guidance</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall provide:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Initial onboarding and operational training.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Standard Operating Procedure (SOP) manuals and periodic updates.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Operational guidelines, best practices, and performance benchmarks.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Periodic audits and reviews for quality and compliance assessment.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Training and audits are advisory in nature and shall not reduce the Franchisee&#8217;s responsibility for execution.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>6.6 Quality Control &amp; Brand Governance</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Set service quality standards and brand guidelines.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Monitor customer experience and brand compliance.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Recommend corrective actions where required.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company reserves the right to take corrective or disciplinary action in case of repeated non-compliance with brand standards.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>6.7 Data, Reporting &amp; Analytics</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Provide access to dashboards, reports, and performance metrics.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Use aggregated data for analytics, optimization, and platform improvement.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Maintain confidentiality and data security as per applicable laws.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>6.8 Limitation of Company Responsibility</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company&#8217;s role is limited to platform enablement and centralized support.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company shall not be responsible for:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Store-level operational losses</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Manpower issues</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Local authority actions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Infrastructure risks</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Nothing in this Agreement shall be construed as creating a partnership, joint venture, or employer&#8211;employee relationship.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7. Service Level Agreement (SLA)</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>This SLA defines mutually agreed service standards to ensure a consistent customer experience on the Dealplex platform, while fairly allocating responsibilities between the Company and the Franchisee.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7.1 Order Acceptance</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Order acceptance by the Franchisee is mandatory during active business hours.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Orders may be rejected only under valid conditions, including:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Inventory unavailability due to system mismatch</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Force majeure events</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>System or platform outage confirmed by the Company</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Unjustified or frequent order rejections shall be considered SLA deviations.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7.2 Delivery Time Commitments</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The standard delivery timeline shall be 10 to 35 minutes, subject to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Distance from store</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Traffic and weather conditions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Peak-hour demand</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Delivery delays caused by:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>App outages</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Payment gateway issues</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Order routing failures</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Platform-level disruptions</span></b><b><span><br></span></b><b><span>shall not be counted as SLA breaches.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7.3 Rider &amp; Operational Readiness</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Franchisee shall ensure reasonable rider availability to meet demand.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company shall support demand forecasting through:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Order flow visibility</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Campaign planning communication</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Unexpected demand spikes due to Company-led promotions shall be considered during SLA evaluation.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7.4 Order Rejection Rate</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company shall define a reasonable rejection threshold, aligned with industry norms.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>If the rejection rate exceeds the threshold:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>The Company may first issue warnings or advisories</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Corrective timelines shall be provided before penalties</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Penalties shall apply only in case of continued non-compliance.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7.5 SLA Monitoring &amp; Fair Assessment</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>SLA performance shall be monitored using Dealplex systems.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>SLA evaluation shall consider:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>System logs</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Delivery constraints</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>External disruptions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>One-off or unavoidable incidents shall not attract punitive action.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7.6 Penalties &amp; Corrective Measures</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Penalties, if applicable, may include:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Monetary deductions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Temporary reduction in order allocation</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Penalty structures shall be:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Pre-defined</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Transparent</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Communicated in advance</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7.7 Repeated SLA Breach</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Repeated, wilful, or negligent SLA violations may constitute a material breach.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Before termination, the Company shall:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Issue written notices</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Provide reasonable opportunity for corrective action</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Termination shall be exercised only as a last resort, except in cases of fraud or intentional misconduct.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7.8 SLA Review &amp; Updates</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>SLA parameters may be revised based on:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Market conditions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Business growth</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Operational learning</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Any revisions shall be communicated in advance and applied prospectively.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><i><span>This SLA is designed to balance customer expectations with operational realities, in line with prevailing quick-commerce industry practices, ensuring fairness and sustainability for both the Company and the Franchisee.</span></i></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Below is a FAIR, BALANCED, and INDUSTRY-STANDARD Revenue &amp; Commission section, clearly protecting both the Company (Dealplex) and the Franchisee, similar to how other quick-commerce platforms operate.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Tone: neutral, professional, legally safe</span></b><b><span><br></span></b><b><span>Use case: Franchise Agreement / Operations Manual</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>8. Revenue &amp; Commission</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>This section defines the revenue sharing and commission mechanism between the Company and the Franchisee in a transparent and mutually beneficial manner.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>8.1 Revenue Sharing Framework</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Revenue generated from orders placed on the Dealplex platform and fulfilled by the Franchisee shall be shared between the Company and the Franchisee as per mutually agreed commercial terms.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The revenue sharing structure may be based on:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Per-order commission</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Margin sharing</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Performance-linked incentives</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The detailed commercial terms shall be specified in Schedule A of this Agreement.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>8.2 Franchisee Earnings &amp; Eligibility</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Franchisee shall earn a commission and/or margin on each successfully fulfilled and delivered order.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Earnings shall not be applicable for:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Orders cancelled by customers before dispatch</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Orders refunded due to Franchisee-side operational issues</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Delays or cancellations caused by platform, payment gateway, or Company-side system issues shall not negatively impact Franchisee earnings.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>8.3 Company Commission &amp; Platform Fees</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company shall be entitled to a commission or platform fee for providing:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Technology infrastructure</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Payment processing</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Marketing and brand support</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Company commissions and applicable charges shall be:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Calculated automatically through the system</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Clearly reflected in settlement statements</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>8.4 Settlements &amp; Payment Cycle</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Net payable amounts shall be settled on a pre-defined cycle (daily / weekly / as agreed).</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Settlement statements shall include:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Gross order value</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Company commission</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Franchisee commission</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Applicable deductions or adjustments</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Any disputes in settlements shall be raised within a defined review period.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>8.5 Refunds, Cancellations &amp; Adjustments</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Refunds due to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Platform errors</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Payment gateway failures</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Customer-initiated cancellations before dispatch</span></b><b><span><br></span></b><b><span>shall be handled by the Company without penalty to the Franchisee.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Refunds due to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Wrong item delivery</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Quality issues</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>SLA breaches attributable to the Franchisee</span></b><b><span><br></span></b><b><span>may be adjusted against Franchisee payouts.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>8.6 Taxes &amp; Statutory Responsibilities</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>All amounts are exclusive of applicable taxes unless stated otherwise.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Each party shall be responsible for its own tax liabilities, including GST, TDS, or other statutory dues.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>8.7 Revision of Commercial Terms</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Commercial terms may be revised by mutual discussion and with prior notice.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Any revisions shall be:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Transparent</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Applied prospectively</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Communicated officially</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>&#160;Fairness &amp; Transparency Clause</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><i><span>Both parties acknowledge that revenue and commission structures are designed to ensure sustainability, transparency, and long-term partnership, in line with prevailing quick-commerce industry practices.</span></i></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>9. Payment &amp; Settlement</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>All customer payments shall be collected through the Company platform.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Net settlements shall be released to the Franchisee on a predefined settlement cycle.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Settlements may include system-based adjustments for:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Returns</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Applicable penalties</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Failed deliveries</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Detailed settlement statements shall be made available for transparency.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>10. Limitation of Liability</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>10.1 Company </span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall not be liable for any losses, costs, or claims arising from:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Store rent, utilities, infrastructure, and manpower expenses</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Inventory loss, theft, pilferage, damage, or shrinkage at the Franchisee store</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Local authority penalties, statutory non-compliance, or regulatory actions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Delivery delays, order failures, or service issues caused by Franchisee operations</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>10.2 Franchisee</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall not be liable for losses arising due to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Mobile application or platform downtime</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Payment gateway, banking, or third-party system failures</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Centralized pricing, discounting, or promotional decisions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Performance of Company-led marketing or demand generation activities</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>11. Term &amp; Termination</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>11.1 Term</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>This Agreement shall remain in force for an initial term of __ years, unless terminated earlier in accordance with this Agreement.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>11.2 Termination</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company may terminate this Agreement, with or without notice, in the event of:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Repeated SLA breaches or service failures</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Fraud, misrepresentation, or misuse of the Dealplex brand</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Continuous or material violation of SOPs or Agreement terms</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Termination shall not affect accrued rights or obligations of either party.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>12. Brand Usage &amp; Confidentiality</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>12.1 Brand Usage</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee is granted a limited, non-transferable right to use the Dealplex brand and trademarks strictly as per Company guidelines and only for the purpose of operating the franchise.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>12.2 Confidentiality</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall maintain strict confidentiality of all non-public information, including:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Pricing logic and commercial terms</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Technology systems, processes, and workflows</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Customer data and business information</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Confidentiality obligations shall continue even after termination of this Agreement.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>13. Governing Law &amp; Jurisdiction</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>This Agreement shall be governed by and construed in accordance with the laws of India, and the courts at Pune, Maharashtra shall have exclusive jurisdiction.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><b><span>SIGNATURE &amp; EXECUTION</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span>IN WITNESS WHEREOF, the Parties hereto have executed this Agreement on the date and place first written above.</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><b><span>For the Company (DEALPLEX)</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span>Name: ______________________________</span><span><br></span><span>Designation: ________________________</span><span><br></span><span>Authorized Signatory</span><span><br></span><span>Signature: __________________________</span><span><br></span><span>Date: ______________________________</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><b><span>For the Franchisee</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><span>Name: ______________________________</span><span><br></span><span>Franchisee Name / Entity: ____________</span><span><br></span><span>Signature: __________________________</span><span><br></span><span>Date: ______________________________</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p></p>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;DEALPLEX DARKSTORE &#8211; LITE</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;FRANCHISE AGREEMENT (Neighbourhood Node)</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>1&#65039;</span></b><b><span><span style=\"font-family:\'Segoe UI Symbol\';\">&#8419;</span></span></b><b><span>&#160;PARTIES</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;This Agreement is entered into between:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Dealplex,a company having its registered office at Office No. 528A, 5th Floor, Gera\'s Imperium Rise, Rajiv Gandhi Infotech Park (Hinjawadi), Pune, Haveli, Maharashtra, India &#8211; 411057,</span></b><b><span><br></span></b><b><span>(hereinafter referred to as the &#8220;Company&#8221;, which expression shall, unless repugnant to the context or meaning thereof, include its successors and permitted assigns),</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>AND</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>[Franchisee Name],</span></b><b><span><br></span></b><b><span>having its registered / principal place of business at [Franchisee Address],</span></b><b><span><br></span></b><b><span>(hereinafter referred to as the &#8220;DarkStore Partner&#8221; or &#8220;Franchisee&#8221;, which expression shall, unless repugnant to the context or meaning thereof, include its successors and permitted assigns).</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>2&#65039;</span></b><b><span><span style=\"font-family:\'Segoe UI Symbol\';\">&#8419;</span></span></b><b><span>&#160;OBJECT OF AGREEMENT</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span>The Company hereby appoints the Franchisee, on a </span><b><span>non-exclusive, limited and revocable basis</span></b><span>, to establish, operate and manage a </span><b><span>Dealplex DarkStore &#8211; LITE</span></b><span>, functioning as a </span><b><span>Neighbourhood Node</span></b><span>, solely for the purpose of fulfilling </span><b><span>hyperlocal quick commerce orders</span></b><span>&#160;generated through the Company&#8217;s technology platform, within such </span><b><span>micro-catchment area as may be allocated, modified or re-defined by the Company from time to time</span></b><span>.</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><span>The Franchisee expressly acknowledges that the Company shall have </span><b><span>absolute discretion and control</span></b><span>&#160;over the business model, technology platform, product catalogue, pricing, promotional schemes, order allocation and service standards, and that the Franchisee shall operate the Dealplex DarkStore &#8211; LITE strictly in accordance with the </span><b><span>policies, standard operating procedures (SOPs), service level requirements and directions</span></b><span>&#160;issued by the Company from time to time.</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><span>The Franchisee shall not use the Dealplex DarkStore &#8211; LITE for any purpose other than the fulfillment of orders routed through the Company&#8217;s platform, nor shall the Franchisee provide similar or competing services, directly or indirectly, without the </span><b><span>prior written consent of the Company</span></b><span>.</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><b><span>3&#65039;</span></b><b><span><span style=\"font-family:\'Segoe UI Symbol\';\">&#8419;</span></span></b><b><span>&#160;STORE FORMAT &amp; PURPOSE</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>3.1 Store Format</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The DarkStore operated under this Agreement shall be designated as &#8220;Dealplex DarkStore &#8211; LITE&#8221;, which shall function as a Neighbourhood Node within the Company&#8217;s hyperlocal quick commerce network. The DarkStore &#8211; LITE shall be a closed-user fulfilment facility and shall not operate as a walk-in retail store or allow direct customer access, except as expressly permitted in writing by the Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>3.2 Purpose of the Store</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The primary purpose of the Dealplex DarkStore &#8211; LITE shall be to enable:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>a) Ultra-fast order fulfillment, with a targeted delivery time of 10 to 30 minutes, subject to demand patterns, traffic conditions, system allocation and operational feasibility;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>b) Low-cost, high-frequency order processing, optimized for daily essentials, fast-moving consumer goods and other categories as determined by the Company from time to time; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>c) Efficient execution of the Company&#8217;s hyperlocal quick commerce strategy, with strict adherence to the operational, service level and quality benchmarks prescribed by the Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>3.3 Target Catchment Area</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Dealplex DarkStore &#8211; LITE shall primarily service dense residential pockets, apartment clusters and high-frequency demand zones, within such delivery radius and micro-catchment area as may be defined, modified, expanded or restricted by the Company at its sole discretion from time to time, based on demand density, network optimisation and service efficiency.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>3.4 Demand Capacity &amp; Performance Expectation</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Dealplex DarkStore &#8211; LITE is designed to support a peak operational capacity of approximately 250 to 1,200 customer orders per day, subject to market conditions, seasonality and operational capability.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee acknowledges that:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The stated demand capacity is indicative and non-guaranteed;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Actual order volumes shall depend on factors including customer demand, marketing initiatives, system allocation and overall network performance; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company shall have the right to re-route, limit or reallocate orders to other fulfilment centres in the interest of service quality and network efficiency.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>3.5 Company Control &amp; Modification Rights</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall have the unrestricted right to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Modify the store format, layout, operating model or service scope;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Change delivery timelines, demand allocation logic or capacity thresholds;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Introduce or withdraw product categories, SKUs or service offerings; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Integrate the Dealplex DarkStore &#8211; LITE into a broader city-level or regional fulfilment strategy.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall implement all such changes without objection and within timelines prescribed by the Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>3.6 No Assurance of Business</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee expressly agrees and acknowledges that:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company does not guarantee any minimum order volume, revenue or profitability; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>All business risks related to demand fluctuation, operational costs and execution shall be borne solely by the Franchisee.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>4&#65039;</span></b><b><span><span style=\"font-family:\'Segoe UI Symbol\';\">&#8419;</span></span></b><b><span>&#160;TERRITORY &amp; CATCHMENT</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>4.1 Defined Delivery Radius</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Dealplex DarkStore &#8211; LITE shall operate within a delivery radius of up to 0 to 3 kilometres, measured from the store location, or such other radius as may be determined, modified, expanded or reduced by the Company from time to time, based on demand density, operational feasibility and network optimisation.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall not deliver orders beyond the permitted delivery radius without the prior written approval of the Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>4.2 Non-Exclusive Territory</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The territory allocated to the Franchisee under this Agreement shall be strictly non-exclusive. The Franchisee expressly acknowledges that:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>No exclusivity, territorial protection or right of first refusal is granted; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company shall be free to appoint additional franchisees, partners, warehouses or fulfilment centres within the same or overlapping territory without any obligation to compensate the Franchisee.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>4.3 Company Rights to Expand Network</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall have the absolute and unrestricted right, at its sole discretion, to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Open, operate or license additional Dealplex DarkStores, warehouses, hubs or fulfilment centres;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Appoint third-party service providers or company-owned stores; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Restructure the fulfilment network within the city or region for operational efficiency.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Such actions shall not constitute a breach of this Agreement nor entitle the Franchisee to any claim, compensation or adjustment.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>4.4 Order Routing &amp; System Logic</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>All customer orders shall be system-assigned through the Company&#8217;s technology platform based on proprietary algorithms, including but not limited to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Distance and rider availability</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Inventory availability</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Store performance and SLA compliance</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Network optimisation parameters</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall have the right to re-route, divert, limit, prioritise or withhold orders from the Franchisee&#8217;s DarkStore at any time, without prior notice, in the interest of service quality, customer experience or operational efficiency.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>4.5 No Right to Demand Orders</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall have no right or entitlement to demand:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>A minimum number of orders</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Guaranteed delivery volume</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Fixed service area or catchment</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee expressly waives any claim arising out of reduction, diversion or reallocation of orders by the Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>4.6 Compliance with Territory Restrictions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall strictly comply with all territorial and catchment limitations as communicated by the Company. Any unauthorised delivery outside the permitted area shall be deemed a material breach of this Agreement and may attract penalties, suspension or termination.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>5&#65039;</span></b><b><span><span style=\"font-family:\'Segoe UI Symbol\';\">&#8419;</span></span></b><b><span>&#160;FRANCHISEE RESPONSIBILITIES</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall be solely, exclusively and entirely responsible for establishing, operating and maintaining the physical infrastructure of the Dealplex DarkStore &#8211; LITE, at its own cost, risk and expense, in accordance with the specifications, standards and directions issued by the Company from time to time.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>5.1 Store Premises</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>a) Identify, lease and retain lawful possession of a suitable premises at its own cost, including payment of rent, security deposit, brokerage and all related charges;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>b) Ensure that the premises is used exclusively for operating the Dealplex DarkStore &#8211; LITE and for no other commercial or non-commercial purpose;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>c) Maintain the premises in a clean, hygienic, safe and operational condition at all times; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>d) Bear full responsibility for any disputes, eviction notices, landlord claims or third-party issues relating to the premises.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall have no responsibility or liability whatsoever in relation to the premises.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>5.2 Utilities &amp; Facilities</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall independently arrange, install, operate and maintain, at its own cost:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Continuous electricity supply with adequate backup</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>High-speed and reliable internet connectivity</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Water supply and sanitation facilities</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>CCTV surveillance systems as per Company specifications</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Fire safety equipment and compliance with applicable safety norms</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Any interruption, failure or deficiency in utilities shall be deemed the sole responsibility of the Franchisee and shall not excuse any breach of service levels or operational obligations.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>5.3 Storage &amp; Equipment</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall procure, install and maintain, at its own expense:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Racks, shelving and storage systems as per Company-approved layout</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Cold storage units, chillers and freezers for temperature-sensitive products</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Backup power for refrigeration equipment</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Any additional equipment required to meet operational or category-specific requirements</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>All equipment shall meet the technical, safety and operational standards prescribed by the Company and shall be subject to inspection and audit.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>5.4 Compliance &amp; Maintenance</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Ensure compliance with all applicable building, fire, safety and municipal regulations;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Carry out regular maintenance, servicing and repairs of the premises and equipment; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Immediately rectify any deficiencies pointed out by the Company or its authorised representatives.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Failure to maintain infrastructure standards may result in penalties, suspension of order routing or termination of this Agreement.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>5.5 No Company Liability</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee expressly acknowledges and agrees that:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company shall not bear any cost relating to rent, utilities, equipment or maintenance;</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company shall not be liable for any loss, damage, accident or disruption arising out of the store premises or infrastructure; and</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>All risks associated with the store and infrastructure shall be borne solely by the Franchisee.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>INVENTORY &amp; OPERATIONS </span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company (Dealplex) shall have exclusive, absolute, and unrestricted rights over the supply of inventory.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>All inventory, stock, products, SKUs, consumables, and saleable items shall be supplied only by </span></b><b><i><span>The Company (Dealplex)</span></i></b><b><span>&#160;or vendors expressly approved by The Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Franchisee shall have zero rights to procure, source, substitute, or stock any product from:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Local markets</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Third-party distributors</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Parallel / grey markets</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Online or offline wholesalers</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company (Dealplex) shall retain absolute control over:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Product assortment</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Brand selection</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Pricing (MRP, selling price, discounts)</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Pack sizes, variants, and discontinuation</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Any violation shall constitute gross misconduct and material breach, entitling The Company to immediate suspension or termination without notice.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>&#160;2. DEALPLEX-APPROVED VENDOR POLICY</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company (Dealplex) may appoint, replace, or remove approved vendors at its sole discretion.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Franchisee shall not negotiate pricing, credit terms, or delivery conditions with any vendor.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>All purchases must be:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Routed strictly through Dealplex ERP / systems</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Billed as per instructions issued by The Company</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>3. INVENTORY OWNERSHIP &amp; CONTROL</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Unless otherwise stated in writing by The Company (Dealplex):</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Inventory shall be deemed Dealplex-authorized stock.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company reserves the right to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Recall inventory</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Replace slow-moving items</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Introduce or discontinue any SKU</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall act only as a custodian of inventory, and not as an independent trader or owner.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span><span style=\"font-family:Calibri;\">&#65533;&#65533;</span> 4. INVENTORY HANDLING &amp; FIFO COMPLIANCE</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall strictly follow Dealplex SOPs, including:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>FIFO (First In First Out)</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Storage &amp; shelving norms</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Temperature, hygiene, and food-safety standards</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>All handling must be exactly as prescribed by The Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>&#160;5. EXPIRY, DAMAGE &amp; UNSALEABLE STOCK</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Expired, damaged, leaked, or tampered stock must be:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Immediately segregated</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Logged in Dealplex systems</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Disposal / return shall be only as instructed by The Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Unauthorized sale or disposal shall attract:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Financial penalties</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Legal action</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Franchise termination</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>6. STOCK LOSS, PILFERAGE &amp; SHRINKAGE</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall be fully and solely liable for:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Theft</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Pilferage</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Mishandling damage</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>System mismatch</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Any shortage shall be entirely borne by the Franchisee, regardless of inventory ownership.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>&#160;MANPOWER (FRANCHISEE RESPONSIBILITY)</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Hiring &amp; management of:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Store Manager</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Pickers / Packers</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Salaries, attendance, discipline, PF/ESI (if applicable) shall be solely Franchisee&#8217;s responsibility.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company (Dealplex) shall have no employer&#8211;employee relationship with store staff.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span><span style=\"font-family:Calibri;\">&#65533;&#65533;</span> LEGAL &amp; REGULATORY COMPLIANCE</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall obtain and maintain:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>GST</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>FSSAI</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Shop &amp; Establishment</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Labour law compliances</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>All penalties, fines, or legal actions due to non-compliance shall be borne solely by the Franchisee, with no liability on The Company (Dealplex).</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span><span style=\"font-family:\'Segoe UI Emoji\';\">&#9878;&#65039; ABSOLUTE RIGHTS OF THE COMPANY (DEALPLEX)</span></span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company (Dealplex) reserves the unrestricted right to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Conduct surprise audits</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Modify inventory mix or pricing</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Impose penalties &amp; deductions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Suspend or terminate franchise operations</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Withhold payouts in case of violations</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>KEY LEGAL STATEMENT </span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span><span style=\"font-family:\'Segoe UI Emoji\';\">&#8220;The Franchisee expressly acknowledges that all inventory supplied under this Agreement is controlled exclusively by The Company, and the Franchisee shall have no independent rights to procure, source, substitute, or deal in any products whatsoever.&#8221;</span></span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>6. Responsibilities of the Company</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company&#8217;s responsibilities under this Agreement shall be limited to providing centralized platform support, brand enablement, and system-level governance. The Company shall not be responsible for day-to-day store operations or local execution.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>6.1 Technology &amp; Platform Infrastructure</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall be responsible for:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Development, maintenance, and operation of the customer mobile application.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Backend systems for order management, routing, and inventory synchronization.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>POS integration as prescribed by the Company.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Centralized payment gateway integration and refund processing.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall make reasonable efforts to ensure system uptime; however, it shall not be liable for disruptions caused by third-party service providers, internet outages, or hardware failures at the store level.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>6.2 Marketing, Branding &amp; Demand Generation</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company may, at its discretion:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Undertake customer acquisition initiatives and app install campaigns.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Execute digital marketing, branding, and promotional activities.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Design and run coupons, cashback, referral programs, and seasonal offers.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company does not guarantee minimum order volume, revenue, or profitability to the Franchisee.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>6.3 Pricing, Catalogue &amp; Commercial Strategy</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall retain centralized control over:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Product catalogue structure and SKU listings.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Pricing, discounting, and promotional offer strategies.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Vendor onboarding, commercial negotiations, and margin structures.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>All pricing and catalogue decisions made by the Company shall be binding on the Franchisee.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>6.4 Vendor &amp; Supply Chain Enablement</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Identify and approve vendors for inventory supply.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Define procurement processes and system workflows.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Monitor supply performance and make changes as required.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall not be responsible for losses arising due to improper storage, mishandling, or negligence at the Franchisee&#8217;s store.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>6.5 Training, SOPs &amp; Operational Guidance</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall provide:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Initial onboarding and operational training.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Standard Operating Procedure (SOP) manuals and periodic updates.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Operational guidelines, best practices, and performance benchmarks.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Periodic audits and reviews for quality and compliance assessment.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Training and audits are advisory in nature and shall not reduce the Franchisee&#8217;s responsibility for execution.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>6.6 Quality Control &amp; Brand Governance</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Set service quality standards and brand guidelines.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Monitor customer experience and brand compliance.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Recommend corrective actions where required.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company reserves the right to take corrective or disciplinary action in case of repeated non-compliance with brand standards.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"></p>\n<hr>\n<p></p>\n<p class=\"MsoNormal\"><b><span>6.7 Data, Reporting &amp; Analytics</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Provide access to dashboards, reports, and performance metrics.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Use aggregated data for analytics, optimization, and platform improvement.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Maintain confidentiality and data security as per applicable laws.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>6.8 Limitation of Company Responsibility</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company&#8217;s role is limited to platform enablement and centralized support.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company shall not be responsible for:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Store-level operational losses</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Manpower issues</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Local authority actions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Infrastructure risks</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Nothing in this Agreement shall be construed as creating a partnership, joint venture, or employer&#8211;employee relationship.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7. Service Level Agreement (SLA)</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>This SLA defines mutually agreed service standards to ensure a consistent customer experience on the Dealplex platform, while fairly allocating responsibilities between the Company and the Franchisee.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7.1 Order Acceptance</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Order acceptance by the Franchisee is mandatory during active business hours.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Orders may be rejected only under valid conditions, including:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Inventory unavailability due to system mismatch</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Force majeure events</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>System or platform outage confirmed by the Company</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Unjustified or frequent order rejections shall be considered SLA deviations.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7.2 Delivery Time Commitments</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The standard delivery timeline shall be 10 to 35 minutes, subject to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Distance from store</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Traffic and weather conditions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Peak-hour demand</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Delivery delays caused by:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>App outages</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Payment gateway issues</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Order routing failures</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Platform-level disruptions</span></b><b><span><br></span></b><b><span>shall not be counted as SLA breaches.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7.3 Rider &amp; Operational Readiness</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Franchisee shall ensure reasonable rider availability to meet demand.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company shall support demand forecasting through:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Order flow visibility</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Campaign planning communication</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Unexpected demand spikes due to Company-led promotions shall be considered during SLA evaluation.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7.4 Order Rejection Rate</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company shall define a reasonable rejection threshold, aligned with industry norms.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>If the rejection rate exceeds the threshold:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>The Company may first issue warnings or advisories</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Corrective timelines shall be provided before penalties</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Penalties shall apply only in case of continued non-compliance.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7.5 SLA Monitoring &amp; Fair Assessment</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>SLA performance shall be monitored using Dealplex systems.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>SLA evaluation shall consider:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>System logs</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Delivery constraints</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>External disruptions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>One-off or unavoidable incidents shall not attract punitive action.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7.6 Penalties &amp; Corrective Measures</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Penalties, if applicable, may include:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Monetary deductions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Temporary reduction in order allocation</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Penalty structures shall be:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Pre-defined</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Transparent</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Communicated in advance</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7.7 Repeated SLA Breach</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Repeated, wilful, or negligent SLA violations may constitute a material breach.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Before termination, the Company shall:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Issue written notices</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Provide reasonable opportunity for corrective action</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Termination shall be exercised only as a last resort, except in cases of fraud or intentional misconduct.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>7.8 SLA Review &amp; Updates</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>SLA parameters may be revised based on:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Market conditions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Business growth</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Operational learning</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Any revisions shall be communicated in advance and applied prospectively.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><i><span>This SLA is designed to balance customer expectations with operational realities, in line with prevailing quick-commerce industry practices, ensuring fairness and sustainability for both the Company and the Franchisee.</span></i></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Below is a FAIR, BALANCED, and INDUSTRY-STANDARD Revenue &amp; Commission section, clearly protecting both the Company (Dealplex) and the Franchisee, similar to how other quick-commerce platforms operate.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Tone: neutral, professional, legally safe</span></b><b><span><br></span></b><b><span>Use case: Franchise Agreement / Operations Manual</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>8. Revenue &amp; Commission</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>This section defines the revenue sharing and commission mechanism between the Company and the Franchisee in a transparent and mutually beneficial manner.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>8.1 Revenue Sharing Framework</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Revenue generated from orders placed on the Dealplex platform and fulfilled by the Franchisee shall be shared between the Company and the Franchisee as per mutually agreed commercial terms.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The revenue sharing structure may be based on:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Per-order commission</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Margin sharing</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Performance-linked incentives</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The detailed commercial terms shall be specified in Schedule A of this Agreement.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>8.2 Franchisee Earnings &amp; Eligibility</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Franchisee shall earn a commission and/or margin on each successfully fulfilled and delivered order.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Earnings shall not be applicable for:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Orders cancelled by customers before dispatch</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Orders refunded due to Franchisee-side operational issues</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Delays or cancellations caused by platform, payment gateway, or Company-side system issues shall not negatively impact Franchisee earnings.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>8.3 Company Commission &amp; Platform Fees</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>The Company shall be entitled to a commission or platform fee for providing:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Technology infrastructure</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Payment processing</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Marketing and brand support</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Company commissions and applicable charges shall be:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Calculated automatically through the system</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Clearly reflected in settlement statements</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>8.4 Settlements &amp; Payment Cycle</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Net payable amounts shall be settled on a pre-defined cycle (daily / weekly / as agreed).</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Settlement statements shall include:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Gross order value</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Company commission</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Franchisee commission</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Applicable deductions or adjustments</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Any disputes in settlements shall be raised within a defined review period.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>8.5 Refunds, Cancellations &amp; Adjustments</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Refunds due to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Platform errors</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Payment gateway failures</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Customer-initiated cancellations before dispatch</span></b><b><span><br></span></b><b><span>shall be handled by the Company without penalty to the Franchisee.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Refunds due to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Wrong item delivery</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Quality issues</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>SLA breaches attributable to the Franchisee</span></b><b><span><br></span></b><b><span>may be adjusted against Franchisee payouts.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>8.6 Taxes &amp; Statutory Responsibilities</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>All amounts are exclusive of applicable taxes unless stated otherwise.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Each party shall be responsible for its own tax liabilities, including GST, TDS, or other statutory dues.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>8.7 Revision of Commercial Terms</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Commercial terms may be revised by mutual discussion and with prior notice.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Any revisions shall be:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Transparent</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Applied prospectively</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Communicated officially</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>&#160;Fairness &amp; Transparency Clause</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><i><span>Both parties acknowledge that revenue and commission structures are designed to ensure sustainability, transparency, and long-term partnership, in line with prevailing quick-commerce industry practices.</span></i></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>9. Payment &amp; Settlement</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>All customer payments shall be collected through the Company platform.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Net settlements shall be released to the Franchisee on a predefined settlement cycle.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Settlements may include system-based adjustments for:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Returns</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Applicable penalties</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>o&#160;</span></span><b><span>Failed deliveries</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Detailed settlement statements shall be made available for transparency.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>10. Limitation of Liability</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>10.1 Company </span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company shall not be liable for any losses, costs, or claims arising from:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Store rent, utilities, infrastructure, and manpower expenses</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Inventory loss, theft, pilferage, damage, or shrinkage at the Franchisee store</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Local authority penalties, statutory non-compliance, or regulatory actions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Delivery delays, order failures, or service issues caused by Franchisee operations</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>10.2 Franchisee</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall not be liable for losses arising due to:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Mobile application or platform downtime</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Payment gateway, banking, or third-party system failures</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Centralized pricing, discounting, or promotional decisions</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Performance of Company-led marketing or demand generation activities</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>11. Term &amp; Termination</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>11.1 Term</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>This Agreement shall remain in force for an initial term of __ years, unless terminated earlier in accordance with this Agreement.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>11.2 Termination</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Company may terminate this Agreement, with or without notice, in the event of:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Repeated SLA breaches or service failures</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Fraud, misrepresentation, or misuse of the Dealplex brand</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Continuous or material violation of SOPs or Agreement terms</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Termination shall not affect accrued rights or obligations of either party.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>12. Brand Usage &amp; Confidentiality</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>12.1 Brand Usage</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee is granted a limited, non-transferable right to use the Dealplex brand and trademarks strictly as per Company guidelines and only for the purpose of operating the franchise.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>12.2 Confidentiality</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>The Franchisee shall maintain strict confidentiality of all non-public information, including:</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Pricing logic and commercial terms</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Technology systems, processes, and workflows</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span><span>&#183;&#160;</span></span><b><span>Customer data and business information</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>Confidentiality obligations shall continue even after termination of this Agreement.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><b><span>13. Governing Law &amp; Jurisdiction</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span>This Agreement shall be governed by and construed in accordance with the laws of India, and the courts at Pune, Maharashtra shall have exclusive jurisdiction.</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><b><span>SIGNATURE &amp; EXECUTION</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span>IN WITNESS WHEREOF, the Parties hereto have executed this Agreement on the date and place first written above.</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><b><span>For the Company (DEALPLEX)</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span>Name: ______________________________</span><span><br></span><span>Designation: ________________________</span><span><br></span><span>Authorized Signatory</span><span><br></span><span>Signature: __________________________</span><span><br></span><span>Date: ______________________________</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><b><span>For the Franchisee</span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><b><span></span></b></p><p><b>&#160;</b></p><b></b>\n<p class=\"MsoNormal\"><span>Name: ______________________________</span><span><br></span><span>Franchisee Name / Entity: ____________</span><span><br></span><span>Signature: __________________________</span><span><br></span><span>Date: ______________________________</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\">&#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160; <span>&#160;</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><b><span>&#160; &#160; &#160; &#160; &#160; &#160; &#160; &#160;Revenue Stamp </span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><b><span>Witnesses</span></b><span></span></p><p></p>\n<p class=\"MsoNormal\"><b><span>Witness 1</span></b><span><br></span><span>Name: ______________________________</span><span><br></span><span>Address: ___________________________</span><span><br></span><span>Signature: __________________________</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><b><span>Witness 2</span></b><span><br></span><span>Name: ______________________________</span><span><br></span><span>Address: ___________________________</span><span><br></span><span>Signature: __________________________</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span>&#160;</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><b><span>&#160;&#160;&#160;Revenue Stamp </span></b><b><span></span></b></p><p><b></b></p><b></b>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><b><span>Witnesses</span></b><span></span></p><p></p>\n<p class=\"MsoNormal\"><b><span>Witness 1</span></b><span><br></span><span>Name: ______________________________</span><span><br></span><span>Address: ___________________________</span><span><br></span><span>Signature: __________________________</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><b><span>Witness 2</span></b><span><br></span><span>Name: ______________________________</span><span><br></span><span>Address: ___________________________</span><span><br></span><span>Signature: __________________________</span><span></span></p><p></p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>\n<p class=\"MsoNormal\"><span></span></p><p>&#160;</p>', 'html');
INSERT INTO `tbltickets` (`ticketid`, `adminreplying`, `userid`, `contactid`, `merged_ticket_id`, `email`, `name`, `department`, `priority`, `status`, `service`, `ticketkey`, `subject`, `message`, `admin`, `date`, `project_id`, `lastreply`, `clientread`, `adminread`, `assigned`, `staff_id_replying`, `cc`) VALUES
(14, 0, 0, 0, NULL, 'testcustomer@example.com', 'Test Customer', 19, 3, 1, 0, 'd94c6d3c5f04c977763a449cd5555ab2', 'Unable to access invoice download link', '<p>Hello Support Team, I recently purchased a subscription plan on your platform and I am unable to download my invoice for the last billing cycle. Every time I click the download invoice link on my account dashboard, the page shows a blank screen and nothing downloads. I have tried this on both Chrome and Firefox browsers, and also tried clearing my cache, but the issue persists. I need this invoice urgently for my company\'s accounting records before the end of this month. Could you please look into this and either fix the download link or send me the invoice PDF directly via email? Thank you for your help.</p>', 1, '2026-09-05 14:03:13', 0, NULL, 0, 1, 1, NULL, NULL),
(15, 0, 0, 0, NULL, 'uat-test@example.invalid', 'UAT Test Requester', 19, 2, 5, 0, 'fc2833a9dd9d7693bb50531c6200c156', 'UAT 2026-09-11 - ticket workflow test (synthetic)', '<p>Synthetic test ticket raised during Module 12 UAT. No customer data. Purpose: verify list, open, reply, assignment, status change and close now that staff are assigned to a department.</p>', 1, '2026-09-11 15:25:41', 0, '2026-09-11 15:29:15', 0, 1, 1, NULL, NULL);
