(1, 'a41c6558274d29b65e2c4c680579f100', 23, 37, 1, 'specific_staff', 'a:1:{i:0;s:1:\"1\";}', 1, 'Techplex Network – Dark Store Partner Application', '[{\"type\":\"header\",\"subtype\":\"h1\",\"label\":\"Become a Techplex Dark Store Partner\",\"className\":\"fw-bold text-center mb-2\"},{\"type\":\"paragraph\",\"subtype\":\"p\",\"label\":\"<blockquote data-start=\'\' data-end=\'\'><p data-start=\'\' data-end=\'\'>Fill the form below to apply for a Techplex Dark Store in your city.<br data-start=\'\' data-end=\'\'>\\nOur expansion team will review your details and contact you within 24 hours with next steps.</p>\\n</blockquote>\",\"className\":\"text-muted text-center mb-3\"},{\"type\":\"file\",\"label\":\"Upload Store Space Photos / Property Documents\",\"description\":\"Please upload photos of your available space, shop, or warehouse (inside & outside view).\",\"placeholder\":\"Choose files to upload\",\"className\":\"form-control\",\"name\":\"file-input\",\"subtype\":\"file\"},{\"type\":\"text\",\"required\":true,\"label\":\"Name\",\"className\":\"form-control\",\"name\":\"name\",\"subtype\":\"text\"},{\"type\":\"text\",\"subtype\":\"email\",\"label\":\"Email Address\",\"className\":\"form-control\",\"name\":\"email\"},{\"type\":\"text\",\"label\":\"Phone\",\"className\":\"form-control\",\"name\":\"phonenumber\",\"subtype\":\"text\"},{\"type\":\"textarea\",\"label\":\"Address\",\"className\":\"form-control\",\"name\":\"address\",\"subtype\":\"textarea\"},{\"type\":\"text\",\"label\":\"City\",\"className\":\"form-control\",\"name\":\"city\",\"subtype\":\"text\"},{\"type\":\"text\",\"label\":\"State\",\"className\":\"form-control\",\"name\":\"state\",\"subtype\":\"text\"},{\"type\":\"select\",\"label\":\"Country\",\"className\":\"form-control\",\"name\":\"country\",\"values\":[{\"label\":\"\",\"value\":\"\"},{\"label\":\"Afghanistan\",\"value\":\"1\"},{\"label\":\"Aland Islands\",\"value\":\"2\"},{\"label\":\"Albania\",\"value\":\"3\"},{\"label\":\"Algeria\",\"value\"